let homeQuery = "";
let photoPreview = "";
function pagePosition() {
 const alphabet = document.getElementById("library-letters");
 return {top:window.scrollY, letters:alphabet ? alphabet.scrollLeft : 0};
}
function restorePosition(position) {
 const alphabet = document.getElementById("library-letters");
 if (alphabet) alphabet.scrollLeft = position.letters;
 window.scrollTo(0,position.top);
}
function rememberPage() {
 const position=pagePosition();
 if(view==="lib"&&cur===null)libraryPosition=position;
 const library = view==="lib" && cur===null ? {q,letter,lang,libraryBook,libraryCategory} : null;
 pageTrail.push({view,cur,position,library});
}
function go(v,x) {
 v=gkGate(v);
 if(v===view&&cur===null&&x===undefined)return;
 rememberPage();
 if(v==="home") {
  pageTrail.length=0;
  pickFt();
 }
 if(v==="lib"){libraryBook="";libraryCategory="";q=x===undefined?"":x;letter="";libraryPosition={top:0,letters:0};}
 if(v==="lib"&&x!==undefined) {
  q=x;
  letter="";
  libraryPosition={top:0,letters:0};
 }
 view=v;
 cur=null;
 render();
 restorePosition(v==="lib"?libraryPosition:{top:0,letters:0});
}
function goBack() {
 const previous=pageTrail.pop();
 if(!previous){
  if(view==="home")return false;
  go("home");
  return true;
 }
 if(view==="lib"&&cur===null)libraryPosition=pagePosition();
 view=previous.view;
 cur=previous.cur;
 if(previous.library){
  q=previous.library.q;
  libraryBook=previous.library.libraryBook||"";libraryCategory=previous.library.libraryCategory||"";
  letter=previous.library.lang===lang ? previous.library.letter : "";
  libraryPosition=previous.position;
 }
 render();
 restorePosition(previous.position);
 return true;
}
