"Tylophora indica / Hemidesmus indicus (to be verified)":{mzj:{ps:"د دویمې درجې ګرم او وچ"},mhy:{ps:"تلپاتې (سدا بهار) بوټی؛ ډیرې غټې اوږدې ریښې او تاوېدونکې تنې؛ ژیړ ګلان چې دننه یې سره دي. په بنګلادېش، سویلي هند او برازیل کې پیدا کېږي."},khs:{ps:"منفث (بلغم لرې کوونکی)، معدې ته ځواک ورکوونکی، قې راوړونکی، معرق."},mzr:{ps:"قې راوړونکی دی؛ ډیر مقدار زهرجنتیا راوستلی شي."},src:TM,gl:["plant","root","seed"]},
"Echinops echinatus":{mzj:{ps:"د دریمې درجې ګرم او وچ"},mhy:{ps:"۱–۲.۵ فوټه لوړ اغزن بوټی؛ ریښې ۴–۶ انچه؛ پاڼې اوږدې، لاندې برخه سپینه وړۍ ډوله؛ سپین ګلان. اوښ یې په ډیره لیوالتیا خوري؛ په شګلنو ځمکو کې پیدا کېږي."},khs:{ps:"معدې ته قوت ورکوونکی، د سړو پړسوبونو محلل، مدر بول، تبه ضد."},mzr:{ps:"ډیر استعمال دماغ او پښتورګو ته زیان رسوي."},msl:{ps:"د انګورو شربت"},bdl:{ps:"انجدان (حلتیت)"},src:TM,gl:["plant","flower"]},
"Mica / Talc (mineral)":{mzj:{ps:"د دویمې درجې سړی او وچ"},mhy:{ps:"معدني توکی؛ طبق پر طبق، ځلاند، تور یا سپین؛ بې خونده؛ په اسانۍ ماتېږي."},khs:{ps:"قابض، مجفف، حابس الدم."},mzr:{ps:"د پښتورګو لپاره زیانمن."},msl:{ps:"د کرفس تخم"},bdl:{ps:"ګل قیمولیا"},src:TM},
"Aloe vera":{mzj:{ps:"د دویمې درجې ګرم او وچ"},mhy:{ps:"ډنډ نه لري؛ د ریښې شاوخوا اغزي لرونکې غټې پاڼې (شاوخوا ۱ فوټ اوږدې)؛ ګلابي ګلان. د پاڼو شېره وچه شي نو مصبر جوړېږي؛ خوند یې سخت تریخ دی."},khs:{ps:"ملین، مسهل، د معدې او ځګر مقوي، د ګېډې چینجي وژونکی، د زخمونو پاکوونکی."},mzr:{ps:"په کولمو کې سوزش پیدا کوي؛ امیندوارو ته د حمل د زیان لامل کېدای شي."},msl:{ps:"کتیرا او سره ګلاب"},bdl:{ps:"تربد، عصاره ریوند"},src:both(HM,TM),gl:["plant","flower","gel","musabbar"]},
"Juglans regia":{mzj:{ps:"دویمه درجه ګرم او وچ (د ځینو په اند ګرم او لوند)"},mhy:{ps:"جنګلي ونه (۱۰۰–۱۲۰ فوټه) او بڼي ونه (۴۰–۹۰ فوټه)؛ مېوه درې پوټکي لري؛ مغز یې خوږ او غوړ. په کشمیر، ایران او افغانستان کې ډیر پیدا کېږي."},khs:{ps:"ملین، محلل، جالی، د ګېډې چینجي وژونکی، وینه پاکوونکی، حابس."},src:TM,gl:["fruit","tree"]}
