// Latest approved plant page: photos, one identity card, grouped source content.
const DETAIL_CARD_GROUPS=[['description',['mhy']],['origin',['origin','source_note']],['properties',['color','mzj','khs','benefit','mzr','msl','bdl','dose']],['chemistry',['chem']],['preparations',['compounds','experience']],['uses',['use']],['notes',['notes']]];
function detailParagraphs(items,direction){
 const paragraphs=[];let previous=null;
 for(const item of items){const last=paragraphs[paragraphs.length-1];if(last&&last.source_ref===item.source_ref&&last.subtitle===item.subtitle)last.text+=' '+item.text;else paragraphs.push({...item});}
 return paragraphs.map(item=>{const title=item.subtitle&&item.subtitle!==previous?'<h4>'+esc(item.subtitle)+'</h4>':'';previous=item.subtitle;return title+'<p lang="'+lang+'" dir="'+direction+'">'+esc(item.text.trim())+'</p>';}).join('');
}
function detailChemistry(record){
 const c=record.chemistry_science?.[lang];if(!c)return '';
 const latin=['Morphine','Codeine','Thebaine','Papaverine','Noscapine'];
 return '<p>'+esc(c.intro)+'</p><table class="chem-table"><thead><tr>'+c.heads.map(h=>'<th scope="col">'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+latin.map((name,i)=>'<tr><th scope="row">'+esc(c.names[i])+(lang==='en'?'':'<span class="compound-latin" dir="ltr" lang="en">'+name+'</span>')+'</th><td>'+esc(c.groups[i<3?0:1])+'</td></tr>').join('')+'</tbody></table><p class="chem-note">'+esc(c.note)+'</p><div class="chem-sources">'+esc(c.source)+': <a href="https://www.unodc.org/pdf/publications/st-nar-29-rev1.pdf" target="_blank" rel="noopener" dir="ltr">UNODC · ST/NAR/29/Rev.1, p. 4</a><br><a href="https://pubmed.ncbi.nlm.nih.gov/18816533/" target="_blank" rel="noopener" dir="ltr">Remberg et al. (2008) · PMID 18816533</a></div>';
}
function wordOrderedPlantDetails(plant) {
 const record=wordDetailLayout.records[plant.taj[0]],copy=wordDetailLayout.meta[lang],fields=record.fields[lang],direction=lang==='en'?'ltr':'rtl';
 const head=(key,body)=>'<div class="detail-identity-block" data-field="'+key+'"><h3>'+esc(copy[key])+'</h3>'+body+'</div>';
 let html=bar(esc(herbDisplay(plant)))+stagePhotoSlots();
 html+='<section class="sec word-detail-field detail-identity-card" data-card="identity">'+
 head('scientific','<p class="scientific-name" dir="ltr" lang="la"><i>'+esc(record.scientific||copy.absent)+'</i></p>')+
 head('family','<p'+(record.family?' dir="ltr" lang="la"':'')+'>'+esc(record.family||copy.absent)+'</p>')+
 head('names',(gkEntryNameRows(record.names[lang],lang).length?'<div class="other-names"><dl>'+gkEntryNameRows(record.names[lang],lang).map(([label,name])=>'<div><dt>'+esc(label)+'</dt><dd dir="auto">'+esc(name)+'</dd></div>').join('')+'</dl></div>':'<p>'+esc(copy.absent)+'</p>')+(record.name_notes[lang]?'<p>'+esc(record.name_notes[lang])+'</p>':''))+'</section>';
 const labels=wordDetailLayout.labels[lang];
 for(const [id,keys] of DETAIL_CARD_GROUPS){
  let body='';
  for(const key of keys){const items=fields[key],table=key==='chem'?record.tables[lang]:null,identity=key==='source_note'?record.identity_note[lang]:null;
   if(!items.length&&!table&&!identity)continue;
   let text=identity?'<p>'+esc(identity)+'</p>':'';
   text+=key==='chem'&&record.chemistry_science?detailChemistry(record):detailParagraphs(items,direction);
   if(table)text+='<h4>'+esc(table.title)+'</h4><p>'+esc(table.note)+'</p><div class="detail-table-wrap"><table class="detail-source-table"><tbody>'+table.rows.map(([name,value])=>'<tr><th scope="row">'+esc(name)+'</th><td dir="ltr">'+esc(value)+'</td></tr>').join('')+'</tbody></table></div>';
   body+='<div class="'+(id==='properties'?'detail-summary-row':'detail-subsection')+'" data-field="'+key+'"><h3>'+esc(labels[key])+(id==='properties'?' :':'')+'</h3>'+text+'</div>';
  }
  if(body)html+='<section class="sec word-detail-field" data-card="'+id+'">'+body+'</section>';
 }
 return html+'<div class="note">'+t().disc+'</div>'+librarySource(plant);
}

