let accountMode='login';
let accountReady=false,googleReady=false,accountSignedIn=false,accountEmail='',accountDisplayName='',accountVerified=false,accountBusy=false,accountFailed=false,accountMessage='';
let authDraftEmail='',authDraftName='';
const authText=()=>authCopy[lang];
function authStatus(){const c=authText();return accountBusy?c.busy:typeof c[accountMessage]==='string'?c[accountMessage]:accountFailed?c.failed:'';}
window.receiveAccountState=function(ready,google,signedIn,email,failed,name='',verified=false,message=''){
 accountReady=!!ready;googleReady=!!google;accountSignedIn=!!signedIn;
 accountEmail=typeof email==='string'?email:'';accountDisplayName=typeof name==='string'?name:'';
 accountVerified=!!verified;accountBusy=false;accountFailed=!!failed;accountMessage=typeof message==='string'?message:'';
 if(accountSignedIn){authDraftEmail=accountEmail;authDraftName=accountDisplayName;}
 else if(accountMessage==='signed_out'){authDraftEmail='';authDraftName='';accountMode='login';}
 if(view==='usr'||view==='set')render();
};
function authBridge(){return window.NativeAccount||window.WebAccount;}
function beginAccountAction(method,args=[]){
 if(accountBusy)return false;
 const bridge=authBridge();
 if(!accountReady||!bridge||typeof bridge[method]!=='function'){
  accountFailed=true;accountMessage='unavailable';const status=document.getElementById('auth-status');if(status)status.textContent=authStatus();return false;
 }
 accountBusy=true;accountFailed=false;accountMessage='';render();
 try{bridge[method](...args);}catch(e){accountBusy=false;accountFailed=true;accountMessage='failed';render();}
 return true;
}
function continueWithGoogle(){if(googleReady)beginAccountAction('google');}
function changeAccountMode(mode){
 if(accountBusy||!['login','signup','reset'].includes(mode))return;
 const form=document.getElementById('auth-form');
 if(form?.elements?.email)authDraftEmail=form.elements.email.value.trim();
 if(form?.elements?.displayName)authDraftName=form.elements.displayName.value.trim();
 accountMode=mode;accountFailed=false;accountMessage='';render();
}
function toggleAuthPassword(id,button){
 const input=document.getElementById(id);if(!input)return;
 const show=input.type==='password';input.type=show?'text':'password';button.textContent=authText()[show?'hide':'show'];button.setAttribute('aria-pressed',String(show));
}
function authFormError(code){accountFailed=true;accountMessage=code;const s=document.getElementById('auth-status');if(s)s.textContent=authStatus();}
function checkAuthForm(event){
 event.preventDefault();if(accountBusy)return;
 const form=event.currentTarget;if(form.reportValidity&&!form.reportValidity())return;
 const email=form.elements.email.value.trim();authDraftEmail=email;
 if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){authFormError('invalid_email');return;}
 if(accountMode==='reset'){beginAccountAction('resetPassword',[email]);return;}
 const password=form.elements.password.value;
 const signup=accountMode==='signup';
 const name=signup?form.elements.displayName.value.trim():'';if(signup)authDraftName=name;
 if(signup&&(!name||name.length>60)){authFormError('invalid_name');return;}
 if(!password||(signup&&password.length<8)){authFormError('weak_password');return;}
 if(signup&&password!==form.elements.confirmPassword.value){authFormError('mismatch');return;}
 // Only pass passwords to the native SDK; never store them in localStorage or draft state.
 beginAccountAction('emailPassword',[signup,email,password,name]);
}
function saveOnlineProfile(event){
 event.preventDefault();if(accountBusy)return;
 const name=event.currentTarget.elements.displayName.value.trim();
 if(!name||name.length>60){authFormError('invalid_name');return;}
 beginAccountAction('updateName',[name]);
}
